import {createEnergyResults} from './energy-results.mjs';
import {faultCatalog,diagnosticSetup,createEnergyFault,energyFaultScore,actEnergyFault} from './energy-faults.mjs';
export function mountEnergyDiagnostic(root,id,{start,changed,exit}){
 const panel=document.createElement('section');panel.className='energy-diagnostic';root.prepend(panel);const names={basic:'Básico',combined:'Combinado',intermittent:'Intermitente',transformload:'Transformador',opamp:'Operacional',relief:'Hidráulica'};let state=null,level='basic';let storage;try{storage=localStorage;}catch{}const results=createEnergyResults(storage);
 function render(message=''){panel.replaceChildren();const el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;panel.append(n);return n;};const button=(text,fn,action)=>{const b=el('button',text);b.onclick=fn;if(action)b.dataset.faultAction=action;return b;};
 el('h2','Taller · avería sorpresa');el('p','Banco A: referencia normal. Banco B: misma consigna con una avería oculta. El diagrama inferior corresponde a A. Usa las lecturas y piezas de B para diagnosticar. Las reparaciones representan intervenciones realizadas con el equipo aislado.');
 if(!state){
 el('h3','Resultados guardados');el('p','Hasta 200 retos completos en este navegador. Los intentos sin terminar no se guardan. Los resultados anteriores a esta función no se pueden recuperar.');if(results.warning())el('p',results.warning());
 const rows=results.all();el('p',rows.length?rows.length+' retos · media '+Math.round(rows.reduce((n,r)=>n+r.score,0)/rows.length)+'/100':'Aún no hay resultados. Completa tu primer diagnóstico.');
 el('h3','Averías que más cuestan');el('p','Ordenadas por errores por reto. En combinados, un error de comprobación se atribuye a cada causa pendiente; no suma errores nuevos a la nota. Pocos intentos no demuestran dominio.');
 for(const st of results.stats())el('p',st.label+' · '+st.n+' retos · '+st.errors+' errores · '+st.hints+' pistas · '+st.rate.toFixed(1)+' errores/reto');
 const history=el('details',''),title=document.createElement('summary');title.textContent='Historial de los últimos 20 resultados';history.append(title);for(const r of rows.slice(-20).reverse()){const p=document.createElement('p');p.textContent=new Date(r.date).toLocaleString('es-CO')+' · '+names[r.lab]+' · '+names[r.level]+' · '+r.score+'/100 · '+r.errors+' errores · '+r.hints+' pistas';history.append(p);}
 const label=el('label','Nivel del siguiente reto '),select=document.createElement('select');select.dataset.faultLevel='';for(const [value,text]of [['basic','Básico · una causa permanente'],['combined','Combinado · dos causas simultáneas'],['intermittent','Intermitente · una causa que aparece y desaparece']]){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option);}select.value=level;select.onchange=()=>{level=select.value;};label.append(select);
 button('Comenzar diagnóstico sorpresa',()=>{state=createEnergyFault(id,Math.random,level);start(state,diagnosticSetup[id]);render('Observa las lecturas sobre las piezas. Puedes pausar y recorrer el tiempo.');},'start');return;}
 el('p','Nivel: '+names[state.level]+' · Causas identificadas: '+state.diagnosedIds.length+' · Reparaciones aplicadas: '+state.repairedIds.length);el('strong','Puntuación: '+energyFaultScore(state)+'/100 · Intentos erróneos: '+state.errors+' · Pistas: '+state.hints);el('p','−15 por diagnóstico, reparación o comprobación incorrectos; −10 por pista. Al completar el reto se guardan nota, errores y pistas en este navegador.');const status=el('p',message||'Compara síntomas antes de intervenir.');status.setAttribute('role','status');status.dataset.faultStatus='';
 if(!state.done){el('h3','1 · Diagnostica');for(const f of faultCatalog[id])button(f.label,()=>action('diagnose',f.id),'diagnose-'+f.id);el('h3','2 · Repara');for(const f of faultCatalog[id])button(f.repair,()=>action('repair',f.id),'repair-'+f.id);button('Pista (−10)',()=>action('hint'),'hint');button('3 · Verificar reparación',()=>action('verify'),'verify');}
 else el('p','Resultado guardado. Reto resuelto. Ambos bancos representan ya el funcionamiento normal; puedes seguir comparándolos.');
 const history=el('details',''),summary=document.createElement('summary');summary.textContent='Bitácora de decisiones';history.append(summary);for(const text of state.log){const p=document.createElement('p');p.textContent=text;history.append(p);}
 button('Salir del diagnóstico',()=>{state=null;exit();render();},'exit');
 }
 function action(action,choice){const msg=actEnergyFault(state,action,choice);if(state.done)results.save(state);changed();render(msg);if(results.warning()){const p=document.createElement('p');p.textContent=results.warning();panel.append(p);}}
 render();return {state:()=>state};
}
